//! The shared branch-name corpus the two `slugify_branch` contract tests run
//! over (`agent-id-slug-safety` design D3).
//!
//! Pulled in with `#[path]` rather than through `helpers/mod.rs` so the two
//! pure-logic test binaries that need it do not also compile the tmux session
//! helpers.
//!
//! Hand-built rather than generated by a property-testing crate: the approved
//! dependency set has none, and the interesting inputs here are enumerable —
//! every printable ASCII character in every position, the separator and
//! underscore shapes PP-26 surfaced, single words, the reserved id, empty and
//! all-separator input, non-ASCII, and the branch shapes git-paw itself
//! builds.
#![allow(dead_code)]

/// Branch names covering every shape the derivation has to be total over.
///
/// Entries are free of newlines and NUL so each one survives a round trip
/// through the shell helper's environment for the bash/Rust parity test.
pub fn branch_corpus() -> Vec<String> {
    let mut corpus: Vec<String> = Vec::new();

    // Every printable ASCII character (0x20..=0x7E) alone, leading, trailing
    // and between two words — the four positions where a character can decide
    // a separator run, a trim, or the whole result.
    for byte in 0x20u8..=0x7E {
        let c = byte as char;
        corpus.push(c.to_string());
        corpus.push(format!("{c}feat"));
        corpus.push(format!("feat{c}"));
        corpus.push(format!("feat{c}x"));
    }

    // Separator, underscore and case shapes.
    for s in [
        "",
        "/",
        "//",
        "///",
        "-",
        "---",
        "_",
        "___",
        "-_-",
        "feat/x",
        "feat//x",
        "/feat/x/",
        "feat/my_feature",
        "feat/a_b",
        "feat/a-b",
        "Feat/HTTP_Broker",
        "FEAT/X",
        "users/jane/feat/x",
        "a/b/c",
        "feat/CVE-2025_1234",
        "fix/CVE-2025_1234",
    ] {
        corpus.push(s.to_string());
    }

    // Single words — the shape the `/publish` validator refuses outright, so
    // the derivation has to lift each of these into a two-segment id.
    for s in [
        "main",
        "master",
        "hotfix",
        "supervisor",
        "agent",
        "x",
        "0",
        "AGENT",
        "Supervisor",
    ] {
        corpus.push(s.to_string());
    }

    // Non-ASCII, including input that survives nothing.
    for s in [
        "feat/日本語",
        "日本語",
        "feat/café",
        "ÄÖÜ",
        "feat/emoji-🐾",
        "🐾",
    ] {
        corpus.push(s.to_string());
    }

    // Characters whose UNICODE lowercase is ASCII, which the ordinary
    // non-ASCII entries above cannot distinguish: every one of those
    // lowercases to something still non-ASCII, so a shell `slugify` that
    // lowercased Unicode-aware before substituting would agree with Rust on
    // them anyway. These two do not — Python's `str.lower()` turns U+0130
    // into `i` (plus a combining dot) and U+212A into `k`, where Rust's
    // `to_ascii_lowercase` leaves both alone for step 2 to replace. They are
    // what gives the parity test teeth over the shell's substitute-then-lower
    // ordering.
    for ch in ['\u{0130}', '\u{212A}'] {
        corpus.push(ch.to_string());
        corpus.push(format!("feat/{ch}"));
        corpus.push(format!("feat/{ch}-x"));
    }

    // The branch shapes git-paw itself builds: `<branch_prefix><spec id>` for
    // the OpenSpec/markdown backends, and the Spec Kit / Superpowers provider
    // branches, which keep `_` (`specs::branch_segment_slug`).
    for s in [
        "spec/add-auth",
        "spec/agent-id-slug-safety",
        "feat/http-broker",
        "fix/db-timeout",
        "chore/bump-deps",
        "task/t009-add-login-form-component",
        "task/t001-create-room_setup-md",
        "phase/003-user-list-foundational",
        "plan/2026-07-20-add-auth",
        "plan/add_auth",
        "plan/agent",
    ] {
        corpus.push(s.to_string());
    }

    corpus
}
